/*
 Problem: 3524. Find X Value of Array I
 Language: cpp
 Runtime: 11 ms (97.33%)
 Memory: 106.3 MB (79.15%)
 Tags: Array, Math, Dynamic Programming
*/
class Solution {
public:
    vector<long long> resultArray(vector<int>& A, int k) {
        vector<long long> res(k);
        int freq[5] = {0};

        for (auto& n : A) {
            n %= k;
            int cur[5] = {0}; //current freq.

            cur[n] = 1;

            for (int x = 0; x < k; x++)
                cur[x * n % k] += freq[x];

            for (int x = 0; x < k; x++) {
                freq[x] = cur[x];
                res[x] += freq[x];
            }
        }

        return res;
    }
};
